// Features/Browse/BrowseView.swift
struct BrowseView: View {
    @State var model: BrowseModel
    var body: some View {
        NavigationStack {
            VStack {
                SearchBar(text: $model.keyword, onSubmit: model.submit)   // 共有コンポーネント（UIViewRepresentable で UISearchBar を包む）
                if model.failed {
                    ErrorView(message: "読み込めませんでした") { model.reload() }   // 共有コンポーネント。メッセージと再読み込みボタンを持つ
                } else {
                    List(model.books) { book in
                        NavigationLink(value: book) {
                            BookRow(book: book)   // 作品名 book.title と著者名 book.author を表示。book.id は画面に出ない
                        }
                    }
                }
            }
            .navigationTitle("さがす")
            .navigationDestination(for: Book.self) { BookDetailView(book: $0) }
        }
    }
}

// Features/Browse/BrowseModel.swift
// keyword が変わると 0.3 秒のデバウンスの後に検索を送る。onSubmit では即座に送る。

